#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    char row[300];
    int total = 2 * n - 1;
    for (int i = 0; i < total; i++) {
        int stars, lead;
        if (i < n) {
            stars = 2 * (n - i) - 1;
            lead = i;
        } else {
            int k = i - n + 1;
            stars = 2 * k + 1;
            lead = total - 1 - i;
        }
        int idx = 0;
        for (int s = 0; s < lead; s++) row[idx++] = ' ';
        for (int s = 0; s < stars; s++) row[idx++] = '*';
        row[idx] = '\0';
        puts(row);
    }
    return 0;
}

