#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    char row[410];
    int mid = n - 1;
    int total = 2 * n - 1;
    for (int i = 0; i < total; i++) {
        int d = (i > mid) ? (i - mid) : (mid - i);
        int right = 2 * (n - 1) - d;
        int width = right + 1;
        for (int k = 0; k < width; k++) row[k] = ' ';
        row[d] = '*';
        row[right] = '*';
        row[width] = '\0';
        puts(row);
    }
    return 0;
}

