#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int m[100][100];
    int val = 1;
    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    while (top <= bottom && left <= right) {
        for (int j = left; j <= right; j++) m[top][j] = val++;
        top++;
        for (int i = top; i <= bottom; i++) m[i][right] = val++;
        right--;
        if (top <= bottom) {
            for (int j = right; j >= left; j--) m[bottom][j] = val++;
            bottom--;
        }
        if (left <= right) {
            for (int i = bottom; i >= top; i--) m[i][left] = val++;
            left++;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j > 0) printf(" ");
            printf("%d", m[i][j]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    char row[410];
    int mid = n - 1;
    int width = 2 * n - 1;
    for (int i = 0; i < width; i++) {
        int k = 0;
        for (int j = 0; j < width; j++) {
            int di = (i > mid) ? (i - mid) : (mid - i);
            int dj = (j > mid) ? (j - mid) : (mid - j);
            int dist = di + dj;
            if (dist <= mid) {
                row[k++] = (char)('0' + (n - dist));
            } else {
                row[k++] = ' ';
            }
        }
        row[k] = '\0';
        int end = k;
        while (end > 0 && row[end - 1] == ' ') end--;
        row[end] = '\0';
        puts(row);
    }
    return 0;
}
